#include <spacerad/OrbitEnvironment.h>
#include <QCoreApplication>
#include <QCryptographicHash>
#include <QDir>
#include <QFile>
#include <QTemporaryDir>
#include <functional>
#include <iostream>
#include <stdexcept>
using namespace spacerad;
namespace {
int count=0;void check(bool ok,const char* name){++count;if(!ok)throw std::runtime_error(name);}
bool rejects(const std::function<void()>& f){try{f();return false;}catch(...){return true;}}
void write(const QString& p,const QByteArray& b){QFile f(p);if(!f.open(QIODevice::WriteOnly|QIODevice::Truncate)||f.write(b)!=b.size())throw std::runtime_error("Cannot write fixture");}
QByteArray bytes(const Json& j){return QByteArray::fromStdString(j.dump(2));}
Json id(const char* n,const QByteArray& b){return {{"file_name",n},{"size_bytes",b.size()},{"sha256",QCryptographicHash::hash(b,QCryptographicHash::Sha256).toHex().toStdString()}};}
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{QTemporaryDir temp;auto root=temp.path();OrbitEnvironmentSettings settings;settings.ephemeris="input.csv";auto config=settings.toJson();check(OrbitEnvironmentSettings::fromJson(config).toJson()==config,"Settings roundtrip");for(const auto& key:{"frame","position_unit"}){auto bad=config;bad[key]="unknown";check(rejects([&]{OrbitEnvironmentSettings::fromJson(bad);}),"Ambiguous frame/units rejected");}auto bad=config;bad["electron_band_MeV"]={.1,5};check(rejects([&]{OrbitEnvironmentSettings::fromJson(bad);}),"Energy model coverage constrained");bad=config;bad["max_gap_seconds"]=false;check(rejects([&]{OrbitEnvironmentSettings::fromJson(bad);}),"Boolean gap rejected");
    QByteArray ephem="utc,x,y,z\n2014-01-01T00:00:18.123456Z,2,0,0\n2014-01-01T00:00:28.123456Z,2,0,0\n2014-01-01T00:00:58.123456Z,2,0,0\n";
    const QStringList utc={"2014-01-01T00:00:18.123456Z","2014-01-01T00:00:28.123456Z","2014-01-01T00:00:58.123456Z"};
    QByteArray orbit="utc,offset_s,x_GEO_Re,y_GEO_Re,z_GEO_Re\n";for(int i=0;i<3;++i)orbit+=utc[i].toUtf8()+','+QByteArray::number(i==0?0:i==1?10:40)+",2,0,0\n";
    write(root+"/input-ephemeris.csv",ephem);write(root+"/orbit.csv",orbit);auto base=Project::demo();base.events=12345;auto baseBytes=bytes(base.toJson());write(root+"/input-project.json",baseBytes);auto p=base;p.name="Synthetic raw-table verification fixture";p.duration=40;p.synthetic=false;p.quantity=engine::SpectrumQuantity::Flux;p.environmentSource="Synthetic test tables only";p.environmentMetadata=engine::defaultEnvironmentMetadata();p.environmentMetadata["model"]="AE8MIN/AP8MIN (IRBEM)";p.environmentMetadata["model_version"]="SpacePy 0.7.0 bundled IRBEM";p.environmentMetadata["statistical_mode"]="Solar minimum maps; ephemeris endpoint trapezoidal time average";p.spectra.clear();Json models=Json::object();
    int label=0;for(const char* name:{"AE8MIN","AP8MIN"}){engine::Spectrum s;s.particle=label++?"proton":"e-";s.interpolation="bin_constant";for(int e=0;e<=32;++e)s.energy.push_back(s.particle=="e-"?.1+e*.01:1+e*.1);s.values.assign(32,4.375);s.prepare();QByteArray raw="utc,threshold_MeV,integral_omnidirectional_flux_cm-2_s-1\n";double scale[3]={2,3,7};for(int i=0;i<3;++i)for(int e=0;e<=32;++e)raw+=utc[i].toUtf8()+','+QByteArray::number(s.energy[e],'g',17)+','+QByteArray::number((s.energy.back()-s.energy[e])*scale[i],'g',17)+'\n';auto file=QString::fromLatin1(name).toLower()+"-integral-flux.csv";write(root+"/"+file,raw);auto identity=id(file.toUtf8().constData(),raw);s.provenance["source_file"]=identity;p.spectra.push_back(s);models[name]={{"particle",s.particle},{"energy_range_MeV",{s.energy.front(),s.energy.back()}},{"bins",32},{"mean_band_flux_cm-2_s-1",s.integral},{"band_fluence_cm-2",s.integral*40},{"valid_integral_values",99},{"scalar_layout_checks",3},{"source_file",identity}};}
    auto document=p.toJson();auto rawProject=bytes(document);write(root+"/project.json",rawProject);Json manifest={{"schema","spacerad.ae8ap8-ephemeris/1"},{"spacepy","0.7.0"},{"samples",3},{"duration_s",40},{"earth_radius_km",6371.2},{"epoch_utc",utc[0].toStdString()},{"interval_end_utc",utc[2].toStdString()},{"frame","GEO"},{"input_position_unit","Re"},{"max_gap_s",30},{"input_ephemeris",id("input.csv",ephem)},{"orbit",id("orbit.csv",orbit)},{"base_project",id("base.json",baseBytes)},{"models",models},{"project",id("project.json",rawProject)}};write(root+"/environment-manifest.json",bytes(manifest));auto review=loadOrbitEnvironment(root);check(review.at("duration_s")==40&&review.at("samples")==3,"Microsecond UTC and unequal intervals reconstruct");check(review.at("project").at("events")==12345,"Base transport settings preserved");check(std::abs(review.at("band_flux_cm-2_s-1").at("e-").get<double>()-4.375*.32)<1e-12,"Endpoint trapezoid preserves physical flux");
    auto wrong=document;wrong["environment"]["spectra"][0]["values"][0]=5;auto b=bytes(wrong);write(root+"/project.json",b);auto altered=manifest;altered["project"]=id("project.json",b);write(root+"/environment-manifest.json",bytes(altered));check(rejects([&]{loadOrbitEnvironment(root);}),"Rehashed wrong spectrum rejected by independent raw fold");write(root+"/project.json",rawProject);write(root+"/environment-manifest.json",bytes(manifest));
    wrong=document;wrong["events"]=12346;b=bytes(wrong);write(root+"/project.json",b);altered=manifest;altered["project"]=id("project.json",b);write(root+"/environment-manifest.json",bytes(altered));check(rejects([&]{loadOrbitEnvironment(root);}),"Rehashed changed geometry/run snapshot rejected");write(root+"/project.json",rawProject);write(root+"/environment-manifest.json",bytes(manifest));
    altered=manifest;altered["duration_s"]=41;write(root+"/environment-manifest.json",bytes(altered));check(rejects([&]{loadOrbitEnvironment(root);}),"Exposure mismatch rejected");write(root+"/environment-manifest.json",bytes(manifest));write(root+"/input-ephemeris.csv",ephem+" ");check(rejects([&]{loadOrbitEnvironment(root);}),"Input ephemeris mutation rejected");
    auto runtime=Json{{"schema","spacerad.orbit-model-runtime/1"},{"python","python.exe"},{"tools_directory","tools"},{"timeout_seconds",300}};write(root+"/runtime.json",bytes(runtime));check(loadOrbitModelRuntime(root+"/runtime.json").python==root+"/python.exe","Runtime paths resolve relative to file");OrbitEnvironmentService service;check(service.state()=="ready"&&!service.running()&&service.result().isEmpty(),"Initial service idle");std::cout<<count<<" orbit environment contract checks\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
